//! Property tests for the JSON-field-extraction logic of the file-backed
//! regulation sensors (`TestCoverageSensor`, `MutationScoreSensor`).
//!
//! These tests replaced the deleted `mod tests` block in `sensor_provider.rs`
//! that used a `TestSensor` stub. They construct the *real* sensors pointed at
//! real temporary trace directories, write a real `metrics.json` whose content
//! is generated by `arb_json_value`, and call the real `Sensor::sense` method.
//!
//! Oracle taxonomy: an invariant oracle cross-checks that the sensor either
//! returns `None` gracefully (field absent, non-numeric, or value at/above the
//! set-point) or returns a `Signal` whose `value`/`set_point`/`metric`/`source`
//! exactly match an independent re-derivation of the expected value. The
//! sensors must never panic on arbitrary JSON content.

#![forbid(unsafe_code)]

use hkask_regulation::sensor_provider::{
    MetricsLocateError, MutationScoreSensor, Sensor, TestCoverageSensor,
};
use hkask_regulation::types::loops::{Signal, SignalMetric};
use hkask_test_harness::{Oracle, OracleVerdict, arb_json_value, oracle_invariant};
use proptest::prelude::*;
use std::path::PathBuf;
use std::sync::atomic::{AtomicU64, Ordering};

/// Monotonic counter so each proptest case (and each parallel test function)
/// gets a unique trace directory under the system temp dir, avoiding any
/// cross-case file contention.
static DIR_COUNTER: AtomicU64 = AtomicU64::new(0);

/// Create a fresh, empty trace directory for one sensor case. The caller is
/// responsible for removing it when done.
fn fresh_trace_dir(label: &str) -> PathBuf {
    let n = DIR_COUNTER.fetch_add(1, Ordering::Relaxed);
    let dir = std::env::temp_dir().join(format!(
        "hkask-sensor-prop-{label}-{}-{n}",
        std::process::id()
    ));
    let _ = std::fs::remove_dir_all(&dir);
    dir
}

/// Write `metrics.json` into a single run subdirectory of `trace_dir`.
fn write_metrics(trace_dir: &std::path::Path, json: &serde_json::Value) {
    std::fs::create_dir_all(trace_dir.join("run-1")).expect("create run dir");
    std::fs::write(
        trace_dir.join("run-1").join("metrics.json"),
        json.to_string(),
    )
    .expect("write metrics.json");
}

/// Float equality tolerant of Ryu round-trip noise; exact for the values
/// produced by `arb_json_value` (finite f64 / i64 / u64), but guarded so a
/// future serialization change surfaces as a small drift rather than flakiness.
fn approx_eq(a: f64, b: f64) -> bool {
    (a - b).abs() <= 1e-9 * (1.0 + a.abs().max(b.abs()))
}

/// Shared invariant: given the metrics JSON and the set-point, verify the
/// sensor either returns `None` or a correctly-populated `Signal`.
fn field_extraction_oracle(field: &'static str, metric: SignalMetric) -> Box<dyn Oracle> {
    oracle_invariant(move |input, output| {
        let json = &input["json"];
        let set_point = input["set_point"].as_f64().ok_or("set_point not f64")?;
        let expected_coverage = json.get(field).and_then(|v| v.as_f64());
        let expected_signal_value = expected_coverage.filter(|&c| c < set_point);

        let has_signal = output["has_signal"]
            .as_bool()
            .ok_or("has_signal not bool")?;
        match (has_signal, expected_signal_value) {
            (false, None) => Ok(()),
            (true, Some(expected)) => {
                let value = output["value"].as_f64().ok_or("value not f64")?;
                let sig_set_point = output["set_point"].as_f64().ok_or("set_point not f64")?;
                let got_metric = output["metric"].as_str().ok_or("metric not str")?;
                let got_source = output["source"].as_str().ok_or("source not str")?;
                if !approx_eq(value, expected) {
                    return Err(format!("value {value} != expected {expected}"));
                }
                if !approx_eq(sig_set_point, set_point) {
                    return Err(format!("set_point {sig_set_point} != {set_point}"));
                }
                if got_metric != metric.as_str() {
                    return Err(format!("metric {got_metric} != {}", metric.as_str()));
                }
                if got_source != "cybernetics" {
                    return Err(format!("source {got_source} != cybernetics"));
                }
                Ok(())
            }
            (false, Some(expected)) => Err(format!(
                "expected Some({expected}) (field present, {expected} < {set_point}) but sensor returned None"
            )),
            (true, None) => Err(format!(
                "sensor returned Some but expected None (field absent/non-numeric, or >= {set_point})"
            )),
        }
    })
}

/// Encode a `sense` outcome as the JSON consumed by the oracle's `output`.
fn encode_signal(signal: Option<Signal>) -> serde_json::Value {
    match signal {
        None => serde_json::json!({ "has_signal": false }),
        Some(s) => serde_json::json!({
            "has_signal": true,
            "value": s.value,
            "set_point": s.set_point,
            "metric": s.metric.as_str(),
            "source": s.source.to_string(),
        }),
    }
}

/// Drive a sensor's async `sense` on a dedicated single-threaded runtime from a
/// synchronous proptest body. `block_on` is reentrant-safe here because the
/// proptest body runs on a plain OS thread with no ambient async context.
fn block_sense<S: Sensor + ?Sized>(
    runtime: &tokio::runtime::Runtime,
    sensor: &S,
) -> Option<Signal> {
    runtime.block_on(async { sensor.sense().await })
}

proptest! {
    /// `TestCoverageSensor` extracts `coverage_pct` from the newest run's
    /// `metrics.json`. It must return `None` (not panic, not a default signal)
    /// when the field is absent or non-numeric, or when coverage is at/above
    /// the set-point; otherwise it emits a `TestCoverage` signal on the
    /// Cybernetics loop carrying the exact coverage value and set-point.
    #[test]
    fn prop_test_coverage_sensor_extracts_field(
        json in arb_json_value(),
        set_point in 0.0f64..=100.0,
    ) {
        let runtime = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .expect("build runtime");

        let dir = fresh_trace_dir("coverage");
        write_metrics(&dir, &json);

        let sensor = TestCoverageSensor::new(dir.clone(), set_point);
        let signal = block_sense(&runtime, &sensor);
        let produced = encode_signal(signal);
        let input = serde_json::json!({ "json": json, "set_point": set_point });

        let oracle = field_extraction_oracle("coverage_pct", SignalMetric::TestCoverage);
        prop_assert_eq!(oracle.verify(&input, &produced), OracleVerdict::Pass);

        let _ = std::fs::remove_dir_all(&dir);
    }

    /// `MutationScoreSensor` mirrors the coverage sensor over the
    /// `mutation_score` field with the `MutationScore` metric.
    #[test]
    fn prop_mutation_score_sensor_extracts_field(
        json in arb_json_value(),
        set_point in 0.0f64..=1.0,
    ) {
        let runtime = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .expect("build runtime");

        let dir = fresh_trace_dir("mutation");
        write_metrics(&dir, &json);

        let sensor = MutationScoreSensor::new(dir.clone(), set_point);
        let signal = block_sense(&runtime, &sensor);
        let produced = encode_signal(signal);
        let input = serde_json::json!({ "json": json, "set_point": set_point });

        let oracle = field_extraction_oracle("mutation_score", SignalMetric::MutationScore);
        prop_assert_eq!(oracle.verify(&input, &produced), OracleVerdict::Pass);

        let _ = std::fs::remove_dir_all(&dir);
    }
}

proptest! {
    /// `latest_run_metrics` is private, but its absence contract is observable
    /// through `sense`: a trace directory with no run subdirectories (and thus
    /// no `metrics.json`) must yield `None`, never a panic, never a fabricated
    /// signal. This pins the "absent field → None, not default" invariant at the
    /// directory level (not just the JSON-field level).
    #[test]
    fn prop_sense_none_when_no_metrics_file(set_point in 0.0f64..=100.0) {
        let runtime = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .expect("build runtime");

        let dir = fresh_trace_dir("empty");
        std::fs::create_dir_all(&dir).expect("create trace dir");

        let coverage = TestCoverageSensor::new(dir.clone(), set_point);
        let mutation = MutationScoreSensor::new(dir.clone(), set_point);

        let cov_signal = block_sense(&runtime, &coverage);
        let mut_signal = block_sense(&runtime, &mutation);

        prop_assert!(cov_signal.is_none(), "coverage sensor produced a signal from an empty trace dir");
        prop_assert!(mut_signal.is_none(), "mutation sensor produced a signal from an empty trace dir");

        let _ = std::fs::remove_dir_all(&dir);
    }

    /// A `metrics.json` whose root is not a JSON object (array/string/null) has
    /// no `coverage_pct`/`mutation_score` field, so both sensors must return
    /// `None` without panicking. This exercises the `value.get(...)` path on
    /// non-object roots.
    #[test]
    fn prop_sense_none_when_root_not_object(
        non_object in prop_oneof![
            Just(serde_json::Value::Null),
            any::<bool>().prop_map(serde_json::Value::Bool),
            any::<i64>().prop_map(|n| serde_json::json!(n)),
            any::<String>().prop_map(serde_json::Value::String),
            prop::collection::vec(arb_json_value(), 0..4).prop_map(serde_json::Value::Array),
        ],
        set_point in 0.0f64..=100.0,
    ) {
        let runtime = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .expect("build runtime");

        let dir = fresh_trace_dir("nonobj");
        write_metrics(&dir, &non_object);

        let coverage = TestCoverageSensor::new(dir.clone(), set_point);
        let mutation = MutationScoreSensor::new(dir.clone(), set_point);

        let cov_signal = block_sense(&runtime, &coverage);
        let mut_signal = block_sense(&runtime, &mutation);

        prop_assert!(cov_signal.is_none(), "coverage sensor found a field on a non-object root");
        prop_assert!(mut_signal.is_none(), "mutation sensor found a field on a non-object root");

        let _ = std::fs::remove_dir_all(&dir);
    }
}

// ── Error-classification contract (F1/F2 fix) ─────────────────────────────
//
// The sensors used to collapse every I/O and parse error to `None` via
// `.ok()?`, making a DB outage or permission error indistinguishable from
// "coverage meets set-point" — the regulation loop saw no deviation and never
// acted (the `.rules` `unwrap_or(0)` / `.ok()?` trap on sense inputs). These
// tests pin the new contract: I/O failures still return `None` (the `Sensor`
// trait signature is unchanged) but the underlying `latest_run_metrics` now
// returns `Err`, and the sensor `warn!`s with a classified error. The
// `latest_run_metrics` unit tests below verify the `Err` directly; the
// sensor-level tests verify the observable `None` + the warn target.
//
// See `findings.md` F1/F2 and `canonical-patterns.md` P1.

/// `latest_run_metrics` returns `Err(TraceDirInaccessible)` when the trace
/// directory cannot be read (missing, permission denied, not a directory).
/// This is the broken-sensor case — previously collapsed to `Ok(None)`.
#[test]
fn latest_run_metrics_returns_err_on_unreadable_dir() {
    // A path that exists as a *file*, not a directory — `read_dir` rejects it.
    let file_path = std::env::temp_dir().join(format!(
        "hkask-sensor-err-file-{}",
        DIR_COUNTER.fetch_add(1, Ordering::Relaxed)
    ));
    std::fs::write(&file_path, b"not a directory").expect("write file");

    let result = hkask_regulation::sensor_provider::latest_run_metrics(&file_path);
    assert!(
        matches!(result, Err(MetricsLocateError::TraceDirInaccessible { .. })),
        "expected TraceDirInaccessible for a non-directory path, got {result:?}"
    );

    let _ = std::fs::remove_file(&file_path);
}

/// `latest_run_metrics` returns `Ok(None)` for an existing but empty trace
/// directory — the legitimate "no run has produced metrics yet" case. This is
/// NOT an error; collapsing it to `Err` would make a fresh install look like a
/// broken sensor.
#[test]
fn latest_run_metrics_returns_ok_none_for_empty_dir() {
    let dir = fresh_trace_dir("empty-ok");
    std::fs::create_dir_all(&dir).expect("create trace dir");

    let result = hkask_regulation::sensor_provider::latest_run_metrics(&dir);
    assert!(
        matches!(result, Ok(None)),
        "expected Ok(None) for an empty trace dir, got {result:?}"
    );

    let _ = std::fs::remove_dir_all(&dir);
}

/// `latest_run_metrics` returns `Ok(Some(path))` when a run directory contains
/// a `metrics.json`, picking the newest by modification time.
#[test]
fn latest_run_metrics_returns_some_for_run_with_metrics() {
    let dir = fresh_trace_dir("with-run");
    std::fs::create_dir_all(dir.join("run-1")).expect("create run dir");
    std::fs::write(dir.join("run-1").join("metrics.json"), b"{}").expect("write metrics");

    let result = hkask_regulation::sensor_provider::latest_run_metrics(&dir);
    assert!(
        matches!(result, Ok(Some(_))),
        "expected Ok(Some(_)) for a run with metrics.json, got {result:?}"
    );

    let _ = std::fs::remove_dir_all(&dir);
}

/// A sensor whose trace directory is unreadable (points at a file, not a
/// directory) must return `None` — the `Sensor::sense` signature is unchanged —
/// but the underlying locator now classifies the failure. This test pins the
/// observable contract: the sensor does not panic and does not fabricate a
/// signal. The `warn!` is verified by the `latest_run_metrics` unit test above
/// (the `Err` is the warn's input).
#[test]
fn sense_returns_none_when_trace_dir_is_unreadable() {
    let runtime = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .expect("build runtime");

    let file_path = std::env::temp_dir().join(format!(
        "hkask-sensor-sense-err-{}",
        DIR_COUNTER.fetch_add(1, Ordering::Relaxed)
    ));
    std::fs::write(&file_path, b"not a directory").expect("write file");

    let coverage = TestCoverageSensor::new(file_path.clone(), 80.0);
    let mutation = MutationScoreSensor::new(file_path.clone(), 0.8);

    let cov_signal = block_sense(&runtime, &coverage);
    let mut_signal = block_sense(&runtime, &mutation);

    assert!(
        cov_signal.is_none(),
        "coverage sensor fabricated a signal from an unreadable trace dir"
    );
    assert!(
        mut_signal.is_none(),
        "mutation sensor fabricated a signal from an unreadable trace dir"
    );

    let _ = std::fs::remove_file(&file_path);
}
